// Types over policy/compiled/policy.json (generated by `pv policy compile` from policy/policy.yaml).

export type Persona = "hr_partner" | "manager" | "people_analyst" | "privacy_officer";
export type SystemRole = "executor";
export type Purpose = "employee_relations" | "team_management" | "workforce_analytics" | "privacy_compliance" | "legal_hold_management";
export type DataClass =
  | "direct_identifier"
  | "date_of_birth"
  | "compensation"
  | "performance"
  | "health_leave"
  | "protected_attribute"
  | "job"
  | "coarsened"
  | "pseudonym";
export type TaggedClass = Exclude<DataClass, "job" | "coarsened" | "pseudonym">;
export type Visibility = "allow" | "deny" | "mask_nullify" | "mask_date_year";
export type AssetCategory =
  | "source_exports"
  | "warehouse_tables"
  | "historical_snapshots"
  | "identity_mappings"
  | "derived_datasets"
  | "application_caches";
export type RefKind = "employee_ref" | "analytics_id";
export type ParamType = "string" | "string_array" | "date" | "int";

export interface RetentionRule {
  days?: number;
  months?: number;
  ttl_seconds?: number;
  basis: "object_date" | "period_end" | "month_end" | "cycle_end" | "export_date" | "month" | "month_metadata" | "native";
}

export interface AssetPart {
  name: string;
  location: string | null;
  format: "jsonl" | "csv" | null;
  referenceColumns: string[];
  retention: RetentionRule | null;
}

export interface AssetDef {
  id: string;
  category: AssetCategory;
  store: "r2" | "kv" | "d1" | "warehouse" | "iceberg";
  location: string;
  executor: "worker" | "python";
  rowLevel: boolean;
  erase: "rewrite_objects" | "delete_keys" | "delete_rows" | "dml_delete" | "iceberg_delete" | "dbt_rebuild";
  subjectColumn: string | null;
  referenceColumns: string[];
  parts: AssetPart[];
}

export interface PersonaDef {
  label: string;
  purposes: Purpose[];
  grants: Partial<Record<Purpose, string[]>>;
}

export interface PurposeDef {
  rowScope: "org_units" | "direct_reports" | "all" | "identity_lookup";
  restrictedPopulation: "include" | "exclude";
  terminated: "include" | "exclude";
  ref: RefKind;
  refPrefix: string;
  bqIdentity: string;
  dataset: string;
}

export interface QueryColumn {
  name: string;
  class: DataClass;
  visibility: Visibility;
}

export interface QueryFilter {
  op: "eq" | "in_array" | "prefix_any_ci";
  param: string;
  column?: string;
  columns?: string[];
}

export interface QueryDef {
  id: string;
  purpose: Purpose;
  name: string;
  kind: "function" | "view";
  object: string;
  view: string;
  viewSource: string;
  params: Record<string, ParamType>;
  filters: QueryFilter[];
  pagedBy: string | null;
  limit: number | null;
  orderBy: string[] | null;
  columns: QueryColumn[];
  /** Generated named-query SQL: DuckDB with $name parameters, BigQuery with @name and a {project} placeholder. */
  sql: { duckdb: string; bigquery: string };
}

export interface CompiledPolicy {
  version: number;
  policyHash: string;
  personas: Record<Persona, PersonaDef>;
  systemRoles: Record<SystemRole, { actions: string[] }>;
  purposes: Record<Purpose, PurposeDef>;
  dataClasses: { tagged: TaggedClass[]; untagged: DataClass[] };
  columnClass: Record<string, DataClass>;
  visibility: Record<Purpose, Record<TaggedClass, Visibility>>;
  untaggedVisibility: Record<string, Visibility>;
  queries: Record<string, QueryDef>;
  categories: AssetCategory[];
  assets: AssetDef[];
  retention: { terminated_subject_years: number; kv_ttl_seconds: number };
  verification: {
    matchFullName: boolean;
    tokens: string[];
    exactColumns: string[];
    d1InternalPrefixes: string[];
    d1InternalTables: string[];
    d1StageExclusions: Record<"before_identity_erasure" | "before_redaction", string[]>;
  };
  pseudonyms: { salt: string; infoPrefix: string; messagePrefix: string; length: number; kinds: Record<string, string> };
  /** every Google Cloud name carries this prefix (shared project, SPEC.md section 30.3.8) */
  naming: { prefix: string };
  datasets: { data: string[]; maxTimeTravelHours: number; failSafeDays: number; authorizedSources: string[] };
}

export const PERSONAS: readonly Persona[] = ["hr_partner", "manager", "people_analyst", "privacy_officer"];
export const PURPOSES: readonly Purpose[] = [
  "employee_relations",
  "team_management",
  "workforce_analytics",
  "privacy_compliance",
  "legal_hold_management",
];
export const CATEGORIES: readonly AssetCategory[] = [
  "source_exports",
  "warehouse_tables",
  "historical_snapshots",
  "identity_mappings",
  "derived_datasets",
  "application_caches",
];

export function isPurpose(v: string): v is Purpose {
  return (PURPOSES as readonly string[]).includes(v);
}
